<script lang="ts">
  import type { BuildTask, RuntimeInfo } from '../lib/types';
  import { buildStatus, formatDate } from '../lib/ui';
  import Icon from '../components/Icon.svelte';
  let { tasks, runtime, query, busy, hasProjects, oncreate, oncancel, onrefresh, onsettings, onopen, oncopy }: {
    tasks: BuildTask[]; runtime: RuntimeInfo; query: string; busy: boolean; hasProjects: boolean;
    oncreate: () => void; oncancel: (id: string) => void; onrefresh: () => void; onsettings: () => void;
    onopen: (url: string) => void; oncopy: (text: string) => void;
  } = $props();
  let filter = $state('all');
  let expanded = $state(new Set<string>());
  const visible = $derived(tasks.filter((task) => `${task.projectName} ${task.repository} ${task.sourceRef}`.toLowerCase().includes(query.toLowerCase()) && (filter === 'all' || (filter === 'active' ? ['queued', 'claimed', 'running'].includes(task.status) : ['succeeded', 'failed', 'cancelled'].includes(task.status)))).slice().sort((a, b) => b.createdAt.localeCompare(a.createdAt)));
  function toggle(id: string) { const next = new Set(expanded); if (next.has(id)) next.delete(id); else next.add(id); expanded = next; }
</script>

<div class="page-heading"><div><h1>Agent 任务</h1><p>让你自己的 Agent 获取明确的源码任务，在授权环境中编译。</p></div><button class="button primary" disabled={!hasProjects || busy} onclick={oncreate}><Icon name="plus" size={16} />创建编译任务</button></div>
<div class="agent-connection-card"><span class="connection-icon" class:connected={runtime.agent.enabled}><Icon name={runtime.agent.enabled ? 'connected' : 'disconnected'} size={23} /></span><div><strong>{runtime.agent.enabled ? '本机 Agent 接口已开启' : '本机 Agent 接口未开启'}</strong><p>{runtime.agent.enabled ? `${runtime.agent.address ?? '仅本机连接'} · 需要连接密钥` : '默认关闭。任务可以先创建，开启连接后再交给你的 Agent。'}</p></div><button class="button secondary small" onclick={onsettings}>{runtime.agent.enabled ? '管理连接' : '前往设置'}<Icon name="arrowRight" size={14} /></button></div>
{#if runtime.agent.error}<div class="inline-callout error"><Icon name="alert" size={18} /><div><strong>连接未就绪</strong><span>{runtime.agent.error}</span></div><button class="text-button" onclick={onsettings}>查看设置</button></div>{/if}
<div class="agent-flow"><div><span>01</span><strong>指定项目与源码</strong><small>分支、标签或提交</small></div><Icon name="arrowRight" size={17} /><div><span>02</span><strong>Agent 在外部编译</strong><small>在你的 AI 平台处理</small></div><Icon name="arrowRight" size={17} /><div><span>03</span><strong>返回可追溯结果</strong><small>记录源码提交与构建结果</small></div></div>
<section class="surface"><div class="list-toolbar"><div class="segmented-tabs" aria-label="编译任务筛选"><button class:active={filter === 'all'} onclick={() => filter = 'all'}>全部任务 <span>{tasks.length}</span></button><button class:active={filter === 'active'} onclick={() => filter = 'active'}>待处理 / 进行中</button><button class:active={filter === 'finished'} onclick={() => filter = 'finished'}>已结束</button></div><button class="icon-button" title="刷新编译任务" aria-label="刷新编译任务" disabled={busy} onclick={onrefresh}><Icon name="refresh" size={16} /></button></div>
  {#each visible as task (task.id)}{@const status = buildStatus[task.status]}<article class="build-task"><div class="build-task-main"><span class="task-icon"><Icon name="code" size={22} /></span><div class="build-task-identity"><div><strong>{task.projectName}</strong><span class={`status-badge ${status.tone}`}>{status.label}</span></div><p>{task.repository}<span class="meta-separator">·</span><code>{task.sourceRef}</code><span class="meta-separator">·</span>Windows x64</p></div><button class="icon-button" aria-expanded={expanded.has(task.id)} aria-label={`查看 ${task.projectName} 任务详情`} onclick={() => toggle(task.id)}><Icon name="chevronDown" size={17} /></button></div>
    <div class="build-progress-line"><span class="tiny-dot" class:working={task.status === 'running'}></span><span>{task.error ?? task.progress ?? (task.status === 'queued' ? '等待你连接的 Agent 领取任务' : task.status === 'claimed' ? 'Agent 已领取，等待开始编译' : task.status === 'succeeded' ? '构建结果已返回，请自行核对来源' : task.status === 'cancelled' ? '任务已取消' : '尚未收到新的进度')}</span></div>
    <div class="build-task-bottom"><span>{formatDate(task.createdAt, true)}{#if task.agentName}<span class="meta-separator">·</span>{task.agentName}{/if}</span><div>{#if ['queued', 'claimed', 'running'].includes(task.status)}<button class="text-button muted" disabled={busy} onclick={() => oncancel(task.id)}>取消任务</button>{/if}{#if task.artifactUrl}<span class="status-badge warning">Agent 构建，非上游官方发行</span><button class="button secondary small" onclick={() => onopen(task.artifactUrl!)}>查看构建结果<Icon name="external" size={13} /></button>{/if}</div></div>
    {#if expanded.has(task.id)}<dl class="task-details"><div><dt>任务编号</dt><dd><code>{task.id}</code><button class="icon-button" title="复制任务编号" aria-label="复制任务编号" onclick={() => oncopy(task.id)}><Icon name="copy" size={13} /></button></dd></div><div><dt>源码提交</dt><dd class="mono">{task.sourceCommit ?? '尚未固定提交，Agent 回传时必须说明'}</dd></div><div><dt>任务说明</dt><dd class="pre-wrap">{task.instructions || '没有额外说明'}</dd></div>{#if task.artifactSha256}<div><dt>结果摘要</dt><dd class="mono break-word">{task.artifactSha256}</dd></div>{/if}<div><dt>结果性质</dt><dd>外部 Agent 基于指定源码生成的构建结果。</dd></div></dl>{/if}
  </article>{:else}<div class="empty-state spacious"><span class="empty-icon"><Icon name="agent" size={30} /></span><h3>{query || filter !== 'all' ? '没有匹配的编译任务' : '还没有编译任务'}</h3><p>需要尚未发行的源码版本？先在软件库订阅项目，再创建一项明确的编译任务。</p><button class="button secondary small" disabled={!hasProjects || busy} onclick={oncreate}><Icon name="plus" size={15} />创建任务</button></div>{/each}
</section>
<p class="page-footnote"><Icon name="shield" size={13} />在这里记录任务进度和结果，实际编译由外部 Agent 平台完成。</p>
